TOOL {"ticket_id": "T-1", "code": "def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    chars = list(s)
    i, j = 0, len(chars) - 1
    while i < j:
        if chars[i] not in vowels:
            i += 1
        elif chars[j] not in vowels:
            j -= 1
        else:
