TOOL {"ticket_id": "T-1", "code": "def sumofFactors(n):
    if n <= 0 or n % 2 != 0:
        return 0
    m = n // 2
    total = 0
    i = 1
    while i * i <= m:
        if m % i == 0:
            total += i
            j = m // i
            if j != i:
                total += j
        i += 1
    return 2 * total
"}

